fn solve(input: Vec<char>) -> Vec<char> {
    // Check the prefix "AtCoder "
    let prefix = "AtCoder ";
    let prefix_len = prefix.len();
    
    // Ensure the input starts with "AtCoder "
    if input.len() < prefix_len || !input.iter().take(prefix_len).collect::<String>().eq(prefix) {
        return vec![]; // Invalid input, return empty vector
    }
    
    // Find the start of the name
    let name_start = prefix_len;
    let name_end = input.iter().position(|&c| c == ' ').unwrap(); // Find the first space after the name
    
    // Extract the name
    let name: String = input[name_start..name_end].iter().collect();
    
    // Validate the name format
    if name.is_empty() || !name.chars().next().unwrap().is_uppercase() || !name[1..].chars().all(|c| c.is_lowercase()) {
        return vec![]; // Invalid name format, return empty vector
    }
    
    // Get the initial of the name
    let initial = name.chars().next().unwrap();
    
    // Build the result
    build_result(initial)
}

fn build_result(ch: char) -> Vec<char> {
    let mut result = Vec::new();
    result.push('A');
    result.push(ch);
    result.push('C');
    result.push('\n');
    result
}